namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly FakePaymentProvider _provider;
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new PaymentGateway(_provider);
    }

    #region Constructor

    [TestMethod]
    public void Ctor_NullProvider_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => new PaymentGateway(null!));
        Assert.AreEqual("provider", ex.ParamName);
    }

    #endregion

    #region ChargeAsync — happy path

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsExpectedResult()
    {
        _provider.NextChargeResult = new ChargeResult("chg_123", true);

        var result = await _gateway.ChargeAsync("tok_visa", 49.99m);

        Assert.AreEqual("chg_123", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ForwardsTokenAndAmount()
    {
        await _gateway.ChargeAsync("tok_mastercard", 100m);

        Assert.AreEqual("tok_mastercard", _provider.LastCardToken);
        Assert.AreEqual(100m, _provider.LastAmount);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderDeclinesCharge_ReturnsFalse()
    {
        _provider.NextChargeResult = new ChargeResult("chg_declined", false);

        var result = await _gateway.ChargeAsync("tok_visa", 10m);

        Assert.IsFalse(result.Success);
    }

    #endregion

    #region ChargeAsync — validation

    [TestMethod]
    public async Task ChargeAsync_NullToken_Throws()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(null!, 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyToken_Throws()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("", 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_WhitespaceToken_Throws()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("   ", 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_NonPositiveAmount_Throws(double rawAmount)
    {
        var amount = (decimal)rawAmount;
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_visa", amount));

        Assert.AreEqual("amount", ex.ParamName);
    }

    #endregion

    #region ChargeAsync — provider errors

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_PropagatesException()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("Gateway timeout");

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.ChargeAsync("tok_visa", 25m));
    }

    #endregion

    #region RefundAsync — happy path

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsExpectedResult()
    {
        _provider.NextRefundResult = new RefundResult("ref_456", true);

        var result = await _gateway.RefundAsync("chg_123");

        Assert.AreEqual("ref_456", result.RefundId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ForwardsChargeId()
    {
        await _gateway.RefundAsync("chg_abc");

        Assert.AreEqual("chg_abc", _provider.LastChargeId);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderDeclinesRefund_ReturnsFalse()
    {
        _provider.NextRefundResult = new RefundResult("ref_fail", false);

        var result = await _gateway.RefundAsync("chg_123");

        Assert.IsFalse(result.Success);
    }

    #endregion

    #region RefundAsync — validation

    [TestMethod]
    public async Task RefundAsync_NullChargeId_Throws()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_Throws()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(""));
    }

    [TestMethod]
    public async Task RefundAsync_WhitespaceChargeId_Throws()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync("   "));
    }

    #endregion

    #region RefundAsync — provider errors

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_PropagatesException()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("Service unavailable");

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync("chg_123"));
    }

    #endregion

    #region ProcessWebhook — event routing

    [TestMethod]
    [DataRow("charge.succeeded", EventStatus.Succeeded)]
    [DataRow("charge.failed", EventStatus.Failed)]
    [DataRow("refund.created", EventStatus.Succeeded)]
    public void ProcessWebhook_KnownEventType_ReturnsExpectedStatus(
        string eventType, EventStatus expectedStatus)
    {
        var result = _gateway.ProcessWebhook(eventType, "{\"id\":\"evt_1\"}");

        Assert.AreEqual(expectedStatus, result.Status);
    }

    [TestMethod]
    [DataRow("charge.disputed")]
    [DataRow("unknown.event")]
    [DataRow("payout.created")]
    public void ProcessWebhook_UnknownEventType_ReturnsUnknown(string eventType)
    {
        var result = _gateway.ProcessWebhook(eventType, "{}");

        Assert.AreEqual(EventStatus.Unknown, result.Status);
    }

    [TestMethod]
    public void ProcessWebhook_PreservesPayload()
    {
        const string payload = "{\"charge\":\"chg_123\",\"amount\":500}";

        var result = _gateway.ProcessWebhook("charge.succeeded", payload);

        Assert.AreEqual(payload, result.Payload);
    }

    #endregion

    #region ProcessWebhook — validation

    [TestMethod]
    [DataRow(null, "payload")]
    [DataRow("", "payload")]
    [DataRow("   ", "payload")]
    [DataRow("charge.succeeded", null)]
    [DataRow("charge.succeeded", "")]
    [DataRow("charge.succeeded", "   ")]
    public void ProcessWebhook_InvalidArguments_Throws(string? eventType, string? payload)
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(eventType!, payload!));
    }

    #endregion
}

